def compute(nums):
    total = 0
    i = 0
    while i < len(nums):
        x = nums[i]
        # If divisible by 3, add it and skip the other checks for this element
        if x % 3 == 0:
            total += x
            i += 1
            continue
        # If even, add twice the value; otherwise add the value
        if x % 2 == 0:
            total += x * 2
        else:
            total += x
        # If the number is negative, subtract 1 as an extra penalty
        if x < 0:
            total -= 1
        i += 1
    return total

def compute(seq, initial):
    acc = initial
    flip = False

    def helper(val, step):
        nonlocal acc, flip
        if flip:
            acc -= val * step
        else:
            acc += val * step
        if val % 2 == 0:
            flip = not flip
        return acc

    for i, v in enumerate(seq):
        step = i + 1
        if v < 0:
            acc += helper(abs(v), step)
        elif v % 3 == 0:
            acc = helper(v // 3, step)
        else:
            acc = helper(v, step) + (1 if step % 2 == 0 else 0)
    return acc

def compute(seq, initial):
    acc = initial
    flip = False
    mode = 1

    def helper(val, step):
        nonlocal acc, flip, mode
        # Apply signed scaled update based on current flip and mode
        if flip:
            acc -= mode * val * step
        else:
            acc += mode * val * step
        # Toggle flip when helper sees an even val
        if val % 2 == 0:
            flip = not flip
        # Invert mode on even steps
        if step % 2 == 0:
            mode *= -1
        return acc

    for i, v in enumerate(seq):
        step = i + 1
        if v < 0:
            # negative values: call with abs(v)+1 and then subtract the step
            acc = helper(abs(v) + 1, step) - step
        elif v % 5 == 0:
            # multiples of 5: add the helper's returned acc
            acc += helper(v // 5, step)
        elif v % 2 == 0:
            # even positive values: call helper twice (first with v, then with v//2)
            acc = helper(v, step)
            acc = helper(v // 2, step)
        else:
            # odd non-multiples-of-5: sometimes add a small constant on step multiples of 3
            if step % 3 == 0:
                acc = helper(v, step) + 2
            else:
                acc = helper(v, step)
    return acc

def count_special_numbers(numbers):
